const crypto = require('node:crypto')
const { createMeterReceiver } = require('./meter-frame')
const { readJsonBody, replyJson } = require('./panel-http')
const { meterRoute } = require('./meter-route')

function createMeterRoom ({ room, now = Date.now, staleMs = 1000 }) {
  const sources = new Map(), panels = new Map()
  const ticks = new Set()
  let timer = null
  let generation = 0

  function attach (panelId, bindings) {
    if (panels.has(panelId)) throw Error('Meter panel already registered')
    const points = Object.entries(bindings).filter(([, entry]) => entry.readMeta?.meter)
      .sort(([a], [b]) => a.localeCompare(b))
    if (!points.length || points.length > 256) throw Error('Invalid meter panel size')
    const proposed = new Map()
    for (const [, binding] of points) {
      const meter = meterRoute(binding.readMeta.meter)
      const key = JSON.stringify([binding.device, meter.streamId])
      const previous = sources.get(key)?.route || proposed.get(key)
      if (previous && JSON.stringify(previous) !== JSON.stringify(meter)) throw Error('Conflicting meter stream')
      proposed.set(key, meter)
    }
    const projections = points.map(([id, binding]) => {
      const meter = meterRoute(binding.readMeta.meter)
      const key = JSON.stringify([binding.device, meter.streamId])
      let source = sources.get(key)
      if (source && JSON.stringify(source.route) !== JSON.stringify(meter)) throw Error('Conflicting meter stream')
      if (!source) {
        source = { device: binding.device, route: meter, receiver: null, receivedAt: null,
          revision: 0, refs: new Set(), indices: new Map() }
        sources.set(key, source)
      }
      source.refs.add(panelId)
      return { id, binding, source, key, pointPath: binding.readPath.replace(/^\/\//, '/') }
    })
    const layout = { kind: 'room-meter-layout', panelId, room, epoch: crypto.randomBytes(16).toString('hex'),
      ids: points.map(([id]) => id) }
    const panel = { projections, layout, sequence: 0 }
    panels.set(panelId, panel)
    return layout
  }

  function accept (message) {
    if (!['device-meter-frame', 'device-meter-manifest'].includes(message?.kind)) return false
    const source = sources.get(JSON.stringify([message.device, message.streamId]))
    if (!source || message.path !== (message.kind === 'device-meter-frame'
      ? source.route.eventPath : source.route.manifestPath)) return false
    let data = message.payload
    // AMX Event emits its arguments object; Status emits the string directly.
    if (data && typeof data === 'object' && Object.hasOwn(data, 'data')) data = data.data
    if (typeof data === 'string') {
      if (Buffer.byteLength(data) > 131072) return false
      try { data = JSON.parse(data) } catch (_) { return false }
    }
    if (message.kind === 'device-meter-manifest') {
      let receiver
      try { receiver = createMeterReceiver(data) } catch (_) { return false }
      if (receiver.manifest.streamId !== source.route.streamId) return false
      const previous = source.receiver?.manifest
      if (previous && JSON.stringify(previous) === JSON.stringify(receiver.manifest)) return true
      if (previous?.epoch === receiver.manifest.epoch &&
        receiver.manifest.layoutVersion <= previous.layoutVersion) return false
      source.receiver?.close()
      source.receiver = receiver
      source.indices = new Map(receiver.manifest.points.map((point, index) => [point.path, index]))
      source.receivedAt = null
    } else {
      if (!source.receiver?.accept(data)) return false
      source.receivedAt = now()
    }
    source.revision = ++generation
    return true
  }

  function snapshot (panelId) {
    const panel = panels.get(panelId)
    if (!panel) return null
    const time = now(), values = [], valid = [], versions = new Map()
    for (const { binding, source, key, pointPath } of panel.projections) {
      const manifest = source.receiver?.manifest
      const frame = source.receiver?.snapshot()
      const index = source.indices.get(pointPath)
      const point = manifest?.points[index]
      const age = source.receivedAt === null ? null : Math.max(0, time - source.receivedAt)
      const matches = point && point.type === binding.readMeta.type && point.min === binding.readMeta.min &&
        point.max === binding.readMeta.max && point.unit === (binding.readMeta.unit || '')
      const flag = Boolean(matches && frame?.valid[index] && age !== null && age <= staleMs)
      values.push(flag ? frame.values[index] : null)
      valid.push(flag)
      versions.set(key, { device: source.device, streamId: source.route.streamId,
        epoch: manifest?.epoch || '', seq: frame?.seq || 0, sampleTime: frame?.sampleTime ?? null, ageMs: age })
    }
    return { kind: 'room-meter-frame', panelId, room, epoch: panel.layout.epoch,
      seq: ++panel.sequence, values, valid, sources: [...versions.values()] }
  }

  function revision (panelId) {
    const panel = panels.get(panelId)
    if (!panel) return ''
    const time = now()
    return panel.projections.map(({ source }) => `${source.revision}:${source.receivedAt !== null &&
      time - source.receivedAt <= staleMs}`).join(',')
  }

  function detach (panelId) {
    const panel = panels.get(panelId)
    if (!panel) return
    panels.delete(panelId)
    for (const { source, key } of panel.projections) {
      source.refs.delete(panelId)
      if (!source.refs.size) { source.receiver?.close(); sources.delete(key) }
    }
  }

  return { attach, accept, snapshot, revision, detach,
    onTick (callback) {
      ticks.add(callback)
      if (!timer) { timer = setInterval(() => { for (const tick of ticks) tick() }, 1000 / 30); timer.unref?.() }
      return () => {
        ticks.delete(callback)
        if (!ticks.size) { clearInterval(timer); timer = null }
      }
    },
    stats: () => ({ panels: panels.size, sources: sources.size }) }
}

function createPanelMeter ({ panelId, room, bindings, hub, onSubscribe = () => {} }) {
  const layout = hub.attach(panelId, bindings)
  const tickets = new Map(), subscribers = new Map()
  let closed = false, lastRevision = ''
  const remove = socketId => {
    const entry = subscribers.get(socketId)
    if (entry) entry.socket.off('disconnect', entry.disconnect)
    subscribers.delete(socketId)
  }
  const live = entry => entry.active() && entry.socket.connected
  const emitFrame = (socket, frame) => socket.volatile.emit('control-panel:meter-frame', frame)
  const prune = () => {
    for (const [key, entry] of tickets) if (entry.expiry <= Date.now() || !entry.active()) tickets.delete(key)
    for (const [key, entry] of subscribers) if (!live(entry)) {
      entry.socket.emit('control-panel:meter-ended', { panelId })
      remove(key)
    }
  }
  const stopTick = hub.onTick(() => {
    prune()
    if (closed || !subscribers.size) return
    const revision = hub.revision(panelId)
    if (revision === lastRevision) return
    lastRevision = revision
    const frame = hub.snapshot(panelId)
    for (const { socket } of subscribers.values()) emitFrame(socket, frame)
  })

  return {
    async ticket (req, res, identity, active) {
      if (!new URL(req.url, 'http://localhost').pathname.endsWith('/meter-ticket') || req.method !== 'POST') return false
      if (closed) { replyJson(res, 503, { error: 'Meter channel unavailable' }); return true }
      prune()
      const body = await readJsonBody(req, 4096)
      if (body.room !== room || typeof body.socketId !== 'string' || !body.socketId || body.socketId.length > 128) {
        replyJson(res, 403, { error: 'Meter subscription rejected' }); return true
      }
      if (!req.headers.origin) { replyJson(res, 403, { error: 'Meter subscription needs Origin' }); return true }
      // One outstanding ticket per session and socket keeps retrying clients bounded.
      for (const [key, entry] of tickets) if (entry.token === identity.token && entry.socketId === body.socketId) tickets.delete(key)
      if (tickets.size >= 100) { replyJson(res, 429, { error: 'Meter ticket limit reached' }); return true }
      const ticket = crypto.randomBytes(32).toString('hex')
      tickets.set(ticket, { token: identity.token, socketId: body.socketId,
        expiry: Math.min(identity.expiry, Date.now() + 10000), active })
      replyJson(res, 200, { ticket })
      return true
    },
    hooks: {
      'control-panel:meter-subscribe': (socket, id, ticket) => {
        if (id !== panelId || closed) return
        prune()
        const entry = tickets.get(ticket)
        tickets.delete(ticket)
        if (!entry || !entry.active() || entry.expiry <= Date.now() || entry.socketId !== socket.id || !socket.connected ||
          (!subscribers.has(socket.id) && subscribers.size >= 100)) {
          socket.emit('control-panel:meter-ended', { panelId }); return
        }
        remove(socket.id)
        const disconnect = () => remove(socket.id)
        subscribers.set(socket.id, { socket, active: entry.active, disconnect })
        socket.on('disconnect', disconnect)
        socket.emit('control-panel:meter-ready', layout)
        const initial = hub.snapshot(panelId)
        emitFrame(socket, initial)
        onSubscribe()
      },
      'control-panel:meter-unsubscribe': (socket, id) => { if (id === panelId) remove(socket.id) }
    },
    accept: message => !closed && hub.accept(message),
    stats: () => ({ tickets: tickets.size, subscribers: subscribers.size, ...hub.stats() }),
    close () {
      closed = true
      stopTick()
      tickets.clear()
      for (const entry of subscribers.values()) {
        entry.socket.emit('control-panel:meter-ended', { panelId })
        entry.socket.off('disconnect', entry.disconnect)
      }
      subscribers.clear()
      hub.detach(panelId)
    }
  }
}

module.exports = { createMeterRoom, createPanelMeter }
